    h,w=len(grid),len(grid[0])
    counts={}
    for row in grid:
        for x in row: counts[x]=counts.get(x,0)+1
    bg=max(counts,key=counts.get)
    fg=max((x for x in counts if x!=bg),key=lambda x:counts[x])
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==fg]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts)
    c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if grid[r][c]==bg:
                # Interior hole surrounded in four directions by foreground-connected structure.
                if r>0 and r+1<h and c>0 and c+1<w:
                    # flood background; keep only regions not connected to outside the fg bounds
                    pass
    # The demonstration marks only holes, i.e. components of background enclosed by fg.
    seen=set()
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if grid[r][c]!=bg or (r,c) in seen: continue
            stack=[(r,c)]; comp=[]; seen.add((r,c)); outside=False
            while stack:
                y,x=stack.pop(); comp.append((y,x))
